// Name the progression: hear one line of a real chart and choose the progression that fills its gap.
// The question bank is generated by build_exercises.py from the ChoCo catalog.

import { CHANNELS } from '../engine/arrange'
import { toTicks, type NoteEvent } from '../engine/events'
import { writeMidi } from '../engine/midiWriter'
import type { Timeline } from '../engine/timeline'
import { ROW_CELLS, type BarChord, type Chart, type TimeSignature } from '../music/chart'
import { keyPrefersFlats, noteName, offsetToKey } from '../music/chords'

export interface Question {
  track_id: string
  title: string
  artist: string
  corpus: string
  style: string
  key: number
  minor: boolean | null // null: the source gives no mode and the chords could not settle it
  relaxed: boolean // from the relaxed line rules for rare progressions (may open or close a song)
  time: TimeSignature
  bars: { chords: (BarChord & { step?: number })[]; time?: TimeSignature }[]
}

export interface Progression {
  id: string
  label: string
  chords: string[]
  unique_song_count: number
  questions: Question[]
}

export interface QuestionBank {
  version: number
  source: string
  progressions: Progression[] // most common first, counted in distinct songs
}

export interface Asked {
  progression: Progression
  question: Question
}

export const BANK_URL = `${import.meta.env.BASE_URL}exercises/name-progression.json`
export const ROUND_LENGTH = 10
export const PASS_MARK = 8 // correct answers in a round that unlock the next level
// Progressions with fewer songs than this would repeat the same few questions; they're not offered
export const MIN_QUESTIONS = 5

/** The progressions used by the levels, most common first. */
export function playable(bank: QuestionBank): Progression[] {
  return bank.progressions.filter((p) => p.questions.length >= MIN_QUESTIONS)
}

// ---------- Levels ----------

// Catalog ids (data/common_progressions.json), named here by their numerals
const P = {
  ii_V_I: 'progression-02', II_V_I: 'progression-19', IV_V_I: 'progression-16', I_IV_V: 'progression-01',
  vi_ii_V_I: 'progression-05', IV_V_I_vi: 'progression-08', iv_V_i: 'progression-20',
  I_V_vi_IV: 'progression-03', vi_IV_I_V: 'progression-04', I_vi_IV_V: 'progression-07',
  ii_bII7_I: 'progression-06', ii_bVII7_I: 'progression-12',
  I_bVII_IV_I: 'progression-18', bVI_bVII_I: 'progression-13',
  V_iv_I: 'progression-17', I_III_IV_iv: 'progression-10',
  i_bVII_bVI_V: 'progression-09', i_bVII_bVI_bVII: 'progression-11',
} as const

export interface Level {
  id: string // shown as the level number, e.g. "1.3"
  progressions: string[] // catalog ids
}

const BASICS = [P.ii_V_I, P.II_V_I, P.IV_V_I, P.I_IV_V]
const UP_TO_5 = [...BASICS, P.vi_ii_V_I, P.IV_V_I_vi, P.iv_V_i]
const POP = [P.I_V_vi_IV, P.vi_IV_I_V, P.I_vi_IV_V]

// After level 7, each pair is first practised alone, then together with everything before it
const PAIRS: [string, string][] = [
  [P.ii_bII7_I, P.ii_bVII7_I],
  [P.I_bVII_IV_I, P.bVI_bVII_I],
  [P.V_iv_I, P.I_III_IV_iv],
  [P.i_bVII_bVI_V, P.i_bVII_bVI_bVII],
]

/** The curriculum: pairs of progressions first, then the same chords together, one idea per level. */
function buildLevels(): Level[] {
  const levels: Level[] = [
    { id: '1.1', progressions: [P.ii_V_I, P.II_V_I] },
    { id: '1.2', progressions: [P.IV_V_I, P.I_IV_V] },
    { id: '1.3', progressions: [P.ii_V_I, P.IV_V_I] },
    { id: '1.4', progressions: [P.II_V_I, P.IV_V_I] },
    { id: '2', progressions: BASICS },
    { id: '3', progressions: UP_TO_5.slice(0, 5) },
    { id: '4', progressions: UP_TO_5.slice(0, 6) },
    { id: '5', progressions: UP_TO_5 },
    { id: '6.1', progressions: [P.vi_IV_I_V, P.I_vi_IV_V] },
    { id: '6.2', progressions: [P.I_V_vi_IV, P.I_vi_IV_V] },
    { id: '6.3', progressions: POP },
    { id: '7', progressions: [...UP_TO_5, ...POP] },
  ]
  let all: string[] = [...UP_TO_5, ...POP]
  let number = 8
  for (const pair of PAIRS) {
    all = [...all, ...pair]
    levels.push({ id: String(number++), progressions: pair }, { id: String(number++), progressions: all })
  }
  return levels
}

export const LEVELS: Level[] = buildLevels()
export const CUSTOM_LEVEL = 'custom'
export const MIN_CUSTOM = 2

/** The level after `id` in the curriculum, if any. */
export const nextLevel = (id: string): Level | undefined => {
  const index = LEVELS.findIndex((l) => l.id === id)
  return index < 0 ? undefined : LEVELS[index + 1]
}

/**
 * The answer choices of a level, in catalog order (most common first).
 * The custom level offers the progressions the player selected.
 */
export function levelProgressions(bank: QuestionBank, levelId: string, custom: readonly string[] = []): Progression[] {
  const ids: readonly string[] = levelId === CUSTOM_LEVEL ? custom : (LEVELS.find((l) => l.id === levelId) ?? LEVELS[0]).progressions
  return playable(bank).filter((p) => ids.includes(p.id))
}

/** Short level name for menus: its numerals when it has few progressions. */
export function levelName(bank: QuestionBank, level: Level): string {
  const choices = levelProgressions(bank, level.id)
  return choices.length <= 3 ? choices.map((p) => p.label.replaceAll(' – ', '–')).join(', ') : `${choices.length} progressions`
}

/**
 * Pick one of the choices, then one of its songs, avoiding recently asked songs.
 * `weight` makes some progressions more likely, e.g. the ones often answered wrongly.
 */
export function pickQuestion(
  choices: Progression[], recent: ReadonlySet<string>, random: () => number = Math.random,
  weight: (progression: Progression) => number = () => 1,
): Asked {
  const weights = choices.map(weight)
  let draw = random() * weights.reduce((a, b) => a + b, 0)
  const progression = choices.find((_, i) => (draw -= weights[i]) < 0) ?? choices[choices.length - 1]
  const fresh = progression.questions.filter((q) => !recent.has(questionId(progression, q)))
  const pool = fresh.length ? fresh : progression.questions
  return { progression, question: pool[Math.floor(random() * pool.length)] }
}

/** A stable id of one question, used to avoid asking the same song twice in a round. */
export const questionId = (progression: Progression, question: Question) => `${progression.id}:${question.track_id}`

/** Share the 16-cell row between the bars, giving busier bars more room. */
export function cellWidths(chordCounts: number[]): number[] {
  if (chordCounts.length <= 4) return chordCounts.map(() => 4)
  const minimum = 2
  const weights = chordCounts.map((n) => Math.max(1, n))
  const spare = ROW_CELLS - minimum * weights.length
  const total = weights.reduce((a, b) => a + b, 0)
  const shares = weights.map((w) => (spare * w) / total)
  const cells = shares.map((s) => minimum + Math.floor(s))
  // Hand out what rounding left over to the largest remainders
  const order = shares.map((s, i) => [s - Math.floor(s), i]).sort((a, b) => b[0] - a[0])
  let left = ROW_CELLS - cells.reduce((a, b) => a + b, 0)
  for (const [, i] of order) {
    if (left-- <= 0) break
    cells[i]++
  }
  return cells
}

/**
 * The bar before, the hidden progression and the bar after, on one row.
 * With a smaller `maxBarsPerRow` (phones) a long line is split into two even rows.
 */
export function questionChart(question: Question, styleId: string, maxBarsPerRow = 6): Chart {
  const count = question.bars.length
  const perRow = count > maxBarsPerRow ? Math.ceil(count / 2) : count
  const widths = count > maxBarsPerRow
    ? question.bars.map(() => 4)
    : cellWidths(question.bars.map((bar) => bar.chords.length))
  return {
    format: 'openstand-chart',
    version: 1,
    title: 'Which progression fills the gap?',
    style: styleId,
    key: question.key,
    minor: question.minor === true,
    bpm: 100,
    time: question.time,
    bars: question.bars.map((bar, i) => ({
      chords: bar.chords,
      cells: widths[i],
      time: bar.time,
      rowStart: i % perRow === 0 || undefined,
      barline: i === question.bars.length - 1 ? 'final' : undefined,
    })),
  }
}

/** The written bar sounding at a beat of the timeline, for the playback highlight. */
export function measureAt(timeline: Timeline, beat: number): { measure: number; beatInBar: number; barBeats: number } | null {
  const bar = timeline.bars.findLast((b) => b.start <= beat + 1e-6)
  if (!bar || beat < timeline.countIn || beat >= timeline.totalBeats) return null
  return { measure: bar.measure, beatInBar: beat - bar.start, barBeats: bar.beats }
}

/** Write a short piano-and-bass reference (no drums) for hearing the key. */
function writeReference(bpm: number, bass: NoteEvent[], comp: NoteEvent[]): Uint8Array {
  return writeMidi(bpm, [
    { name: 'Bass', channel: CHANNELS.bass, program: 32, pan: 60, reverb: 20, events: bass },
    { name: 'Piano', channel: CHANNELS.comp, program: 0, pan: 64, reverb: 40, events: comp },
  ])
}

// Keeps the reference voicings around middle C: the tonic moves down for keys above F-sharp
const homeOffset = (keyPc: number) => (keyPc > 6 ? keyPc - 12 : keyPc)

/** A piano note of a reference, `at` and `length` in beats. */
const note = (channel: number, pitch: number, at: number, length: number, velocity = 72): NoteEvent =>
  ({ tick: toTicks(at), channel, note: pitch, velocity, duration: toTicks(length) })

/**
 * The tonic triad: root, third and fifth played one by one, then together over the bass.
 * Without a known mode (`minor` null) the third is left out: root, fifth and octave.
 */
export function tonicMidi(keyPc: number, minor: boolean | null, bpm: number): Uint8Array {
  const root = 60 + homeOffset(keyPc)
  const triad = minor === null ? [root, root + 7] : [root, root + (minor ? 3 : 4), root + 7]
  const comp = [
    ...triad.map((pitch, i) => note(CHANNELS.comp, pitch, i, 0.95)),
    ...[...triad, root + 12].map((pitch) => note(CHANNELS.comp, pitch, 3, 3, 70)),
  ]
  return writeReference(bpm, [note(CHANNELS.bass, root - 24, 3, 3, 80)], comp)
}

/** A sound that sets up the key before listening to a line. */
export type KeyReference = 'tonic' | 'major cadence' | 'minor cadence'

/** The key references to offer: the tonic and the mode's cadence, or both cadences when the mode is unknown. */
export function keyReferences(minor: boolean | null): KeyReference[] {
  if (minor === null) return ['tonic', 'major cadence', 'minor cadence']
  return ['tonic', minor ? 'minor cadence' : 'major cadence']
}

/** The MIDI of one key reference in a key. */
export function keyReferenceMidi(reference: KeyReference, keyPc: number, minor: boolean | null, bpm: number): Uint8Array {
  if (reference === 'tonic') return tonicMidi(keyPc, minor, bpm)
  return cadenceMidi(keyPc, reference === 'minor cadence', bpm)
}

// ---------- Key ----------

/** Song key, a random key for each question, or one fixed tonic (pitch class). */
export type KeyChoice = 'song' | 'random' | number

/** Semitones that move a question to the chosen key. */
export function transposeFor(choice: KeyChoice, question: Pick<Question, 'key'>, random: () => number = Math.random): number {
  if (choice === 'song') return 0
  const tonic = choice === 'random' ? Math.floor(random() * 12) : choice
  return offsetToKey(question.key, tonic)
}

/** A cadence that sets up the key: I-IV-V-I, or i-iv-V-i in minor, then the tonic held. */
export function cadenceMidi(keyPc: number, minor: boolean, bpm: number): Uint8Array {
  const tonic = 60 + homeOffset(keyPc)
  const third = minor ? 3 : 4
  const sixth = minor ? 8 : 9
  // Upper voices move by step above the bass roots (I, IV, V, I); the last chord rings longer
  const chords: [number, number[]][] = [
    [0, [0, third, 7]],
    [5, [0, 5, sixth]],
    [-5, [-1, 2, 7]],
    [0, [0, third, 7]],
  ]
  const bass: NoteEvent[] = []
  const comp: NoteEvent[] = []
  chords.forEach(([root, upper], i) => {
    const length = i === chords.length - 1 ? 3 : 1.9
    bass.push(note(CHANNELS.bass, tonic - 24 + root, i * 2, length, 82))
    for (const pitch of upper) comp.push(note(CHANNELS.comp, tonic + pitch, i * 2, length, 70))
  })
  return writeReference(bpm, bass, comp)
}

// ---------- Hearing another answer in the gap ----------

const DEGREES: Record<string, number> = { I: 0, II: 2, III: 4, IV: 5, V: 7, VI: 9, VII: 11 }
const ROMAN = /^(VII|VI|V|IV|III|II|I)([b#]?):(.+)$/

/** Write a catalog chord (II:min, V:maj, IIb:7) as a chord symbol in a key. */
export function romanSymbol(chord: string, keyPc: number, sevenths: boolean): string {
  const match = ROMAN.exec(chord)
  if (!match) throw new Error(`Unsupported progression chord: ${chord}`)
  const [, numeral, accidental, quality] = match
  const pc = (keyPc + DEGREES[numeral] + (accidental === 'b' ? -1 : accidental === '#' ? 1 : 0) + 12) % 12
  // A flattened degree is spelled with a flat (bII7 in C is Db7), otherwise as the key prefers
  const name = noteName(pc, accidental === 'b' || (accidental !== '#' && keyPrefersFlats(keyPc)))
  // Written sevenths and sixths keep their quality (II:min7 -> D-7, I:maj7 -> C^7, IV:min6 -> F-6)
  const written: Record<string, string> = { maj7: '^7', min7: '-7', min6: '-6' }
  if (quality in written) return name + written[quality]
  if (quality.startsWith('min')) return name + (sevenths ? '-7' : '-')
  if (quality === '7') return `${name}7`
  if (!sevenths) return name
  // In jazz a major chord on II, III, V, VI or VII works as a (secondary) dominant
  const dominant = !accidental && !['I', 'IV'].includes(numeral)
  return name + (dominant ? '7' : '^7')
}

/** The steps of a progression, with repeated neighbours as one step. */
export const progressionSteps = (chords: string[]) => chords.filter((c, i) => c !== chords[i - 1])

/**
 * The same line with another progression in the gap. With as many steps as the real
 * answer it keeps the song's rhythm; otherwise it shares the gap evenly, on whole beats.
 */
export function withProgression(question: Question, chosen: Progression, sevenths: boolean): Question {
  const steps = progressionSteps(chosen.chords)
  const hidden = question.bars.flatMap((bar) => bar.chords.filter((c) => c.hidden))
  const total = hidden.reduce((sum, c) => sum + c.beats, 0)
  const stepStarts: number[] = []
  let at = 0
  for (const c of hidden) {
    if (c.step !== undefined && stepStarts[c.step] === undefined) stepStarts[c.step] = at
    at += c.beats
  }
  let bounds: number[]
  if (stepStarts.length === steps.length && stepStarts.every((s) => s !== undefined)) {
    bounds = [...stepStarts, total]
  } else {
    bounds = steps.map((_, i) => Math.round((i * total) / steps.length))
    for (let i = 1; i < bounds.length; i++) bounds[i] = Math.max(bounds[i], Math.min(bounds[i - 1] + 1, total))
    bounds.push(total)
  }
  const symbols = steps.map((c) => romanSymbol(c, question.key, sevenths))

  let gapAt = 0
  const bars = question.bars.map((bar) => {
    const chords: Question['bars'][number]['chords'] = []
    let filled = false
    for (const c of bar.chords) {
      if (!c.hidden) {
        chords.push(c)
        continue
      }
      if (filled) continue
      // The hidden part of a bar is contiguous: refill all of it at once
      const length = bar.chords.filter((h) => h.hidden).reduce((sum, h) => sum + h.beats, 0)
      const from = gapAt
      const to = gapAt + length
      steps.forEach((_, i) => {
        const beats = Math.min(to, bounds[i + 1]) - Math.max(from, bounds[i])
        if (beats > 1e-6) chords.push({ symbol: symbols[i], beats, hidden: true, step: i })
      })
      gapAt = to
      filled = true
    }
    return { ...bar, chords }
  })
  return { ...question, bars }
}

// ---------- Results ----------

export interface ProgressionResult {
  asked: number
  correct: number
  confusedWith: Record<string, number> // wrong answers given for this progression
}

export type Results = Record<string, ProgressionResult>

/** Count one answer: right or wrong, and which progression was chosen instead. */
export function recordAnswer(results: Results, correctId: string, chosenId: string): Results {
  const before = results[correctId] ?? { asked: 0, correct: 0, confusedWith: {} }
  const right = correctId === chosenId
  return {
    ...results,
    [correctId]: {
      asked: before.asked + 1,
      correct: before.correct + (right ? 1 : 0),
      confusedWith: right ? before.confusedWith : { ...before.confusedWith, [chosenId]: (before.confusedWith[chosenId] ?? 0) + 1 },
    },
  }
}

/** Estimated accuracy; an unseen progression counts as 50 %. */
export function accuracy(result: ProgressionResult | undefined): number {
  return ((result?.correct ?? 0) + 1) / ((result?.asked ?? 0) + 2)
}

/** Question weight when focusing on mistakes: from 0.5 (always right) to 2.5 (always wrong). */
export const mistakeWeight = (result: ProgressionResult | undefined) => 0.5 + 2 * (1 - accuracy(result))

/** The wrong answer most often given for a progression. */
export function mostConfused(result: ProgressionResult | undefined): [string, number] | null {
  const entries = Object.entries(result?.confusedWith ?? {})
  return entries.length ? entries.reduce((best, entry) => (entry[1] > best[1] ? entry : best)) : null
}
